// ============================================================
// NODE 3 — Parse & Validate Form Data
// Built against real Tally payload — noir-collective-france
// Last updated: April 2026
// ============================================================

const FIELD_MAP = {
  'question_AJBrbB': 'full_name',
  'question_B1xEb7': 'email',
  'question_kANbR6': 'phone',
  'question_PEYr95': 'gender',
  'question_7DvbJ9': 'is_minor',
  'question_vBPXxA': 'date_of_birth',
  'question_KoVpBM': 'location_city',
  'question_LGPDMG': 'zip_code',
  'question_pADePV': 'location_country',
  'question_1K9W2M': 'nationality',
  'question_MOE1dY': 'right_to_work_countries',
  'question_JRO1kJ': 'right_to_work_other',
  'question_gA9bNN': 'instagram_url',
  'question_yyJXq0': 'languages_spoken',
  'question_XG45BO': 'languages_other',
  'question_8kZNpA': 'height_cm',
  'question_0MeVjZ': 'bust_cm',
  'question_zz7EQ1': 'waist_cm',
  'question_E1D6lX': 'hips_cm',
  'question_5kZXqM': 'dress_size',
  'question_dA9b2z': 'shoe_size_eu',
  'question_YO4jzq': 'hair_color',
  'question_D17qvb': 'eye_color',
  'question_lA6al5': 'hair_texture',
  'question_R4DWBl': 'skin_tone',
  'question_oB29V1': 'modeling_experience',
  'question_G1ReBj': 'experience_details',
  'question_OP7QBK': 'currently_represented',
  'question_Vlzp1a': 'current_agencies',
  'question_PEzRBQ': 'was_scouted',
  'question_E1xqbo': 'scouted_by',
  'question_rKoDrM': 'special_skills',
  'question_4kKaNb': 'availability',
  'question_bkr922': 'guardian_name',
  'question_AJDK6W': 'guardian_email',
  'question_B1DKLA': 'guardian_phone',
  'question_kAW90J_d18a3420-2d4d-44fd-8cdf-38d8bc9d0d33': 'guardian_consent',
  'question_jMle9R': 'photo_headshot',
  'question_2kKjxp': 'photo_full_body',
  'question_xQJVNG': 'photo_profile',
  'question_R4DWBp': 'photo_three_quarter',
  'question_rKLYOl': 'photo_polaroid',
  'question_vBLr0d_0bb10bdc-f15d-41dd-b574-4acf63bd2d5d': 'gdpr_consent',
  'question_oBdxYO_db5144bf-9125-4f71-8923-536b4d6b9e6f': 'ai_consent',
  'question_KoDePk_ce4f8f70-ab47-4ca5-9af4-10823e74710a': 'accuracy_declaration',
};

function resolveOptions(field) {
  if (!field.options || !field.value) return field.value;
  const optionMap = {};
  field.options.forEach(o => { optionMap[o.id] = o.text; });
  if (Array.isArray(field.value)) {
    return field.value.map(id => optionMap[id] || id).filter(Boolean);
  }
  return optionMap[field.value] || field.value;
}

const fields = $('Form Intake Trigger').first().json.body.data.fields;
const raw = {};

fields.forEach(field => {
  const fieldName = FIELD_MAP[field.key];
  if (!fieldName) return;
  if (field.type === 'FILE_UPLOAD') {
    raw[fieldName] = Array.isArray(field.value) ? field.value : [];
  } else if (field.type === 'DROPDOWN') {
    raw[fieldName] = resolveOptions(field);
    if (Array.isArray(raw[fieldName])) raw[fieldName] = raw[fieldName][0] || null;
  } else if (field.type === 'CHECKBOXES' || field.type === 'MULTI_SELECT') {
    raw[fieldName] = resolveOptions(field);
  } else if (field.type === 'MULTIPLE_CHOICE') {
    raw[fieldName] = resolveOptions(field);
    if (Array.isArray(raw[fieldName])) raw[fieldName] = raw[fieldName][0] || null;
  } else {
    raw[fieldName] = field.value;
  }
});

const config = $('Read Agency Slug').first().json.fields;

const clean = (val) => (val || '').toString().trim();
const cleanLower = (val) => clean(val).toLowerCase();
const toFloat = (val) => { const n = parseFloat(val); return isNaN(n) ? null : n; };
const toBool = (val) => {
  if (val === true || val === 'true' || val === 1) return true;
  if (val === false || val === 'false' || val === 0) return false;
  return null;
};
const toArray = (val) => {
  if (!val) return [];
  if (Array.isArray(val)) return val;
  if (typeof val === 'string') return val.split(',').map(s => s.trim()).filter(Boolean);
  return [];
};
const toDate = (val) => {
  if (!val) return null;
  const d = new Date(val);
  return isNaN(d.getTime()) ? null : d.toISOString().split('T')[0];
};

const data = {
  full_name:            clean(raw.full_name),
  email:                cleanLower(raw.email),
  phone:                clean(raw.phone),
  date_of_birth:        toDate(raw.date_of_birth),
  location_city:        clean(raw.location_city),
  location_country:     clean(raw.location_country),
  nationality:          clean(raw.nationality),
  instagram_url:        clean(raw.instagram_url),
  language:             'EN',
  gender:               clean(raw.gender),
  height_cm:            toFloat(raw.height_cm),
  bust_cm:              toFloat(raw.bust_cm),
  waist_cm:             toFloat(raw.waist_cm),
  hips_cm:              toFloat(raw.hips_cm),
  shoe_size_eu:         toFloat(raw.shoe_size_eu),
  hair_color:           clean(raw.hair_color),
  eye_color:            clean(raw.eye_color),
  skin_tone:            clean(raw.skin_tone),
  hair_texture:         clean(raw.hair_texture),
  modeling_experience:  raw.modeling_experience === 'Yes' ? 'Yes' : 'No',
  experience_details:   clean(raw.experience_details),
  languages_spoken:     toArray(raw.languages_spoken),
  special_skills:       clean(raw.special_skills),
  right_to_work:        Array.isArray(raw.right_to_work_countries) && raw.right_to_work_countries.length > 0,
  availability:         Array.isArray(raw.availability) ? raw.availability.join(', ') : clean(raw.availability),
  gdpr_consent:         toBool(raw.gdpr_consent),
  ai_consent:           toBool(raw.ai_consent),
  guardian_consent:     toBool(raw.guardian_consent) || null,
  consent_date:         new Date().toISOString(),
  agency_slug:          config['Agency Slug'] || 'noir-collective-france',
  application_source:   'tally_form',
  platform_type:        'tally',
  application_stage:    'processing',
  status:               'active',
  batch_processing_status: 'queued',
  storage_type:         'r2',
  is_reapplication:     false,
  cooldown_overridden:  false,
  analysis_run_count:   0,
  photo_resubmission_count: 0,
  _photos: {
    headshot:      raw.photo_headshot      || [],
    full_body:     raw.photo_full_body     || [],
    profile:       raw.photo_profile       || [],
    three_quarter: raw.photo_three_quarter || [],
    polaroid:      raw.photo_polaroid      || [],
  },
};

if (data.languages_spoken.includes('French'))      data.language = 'FR';
else if (data.languages_spoken.includes('Spanish')) data.language = 'ES';
else if (data.languages_spoken.includes('German'))  data.language = 'DE';
else if (data.languages_spoken.includes('Arabic'))  data.language = 'AR';
else if (data.languages_spoken.includes('Hindi'))   data.language = 'HI';
else                                                data.language = 'EN';

const errors = [];
if (!data.full_name)            errors.push('full_name is required');
if (!data.email)                errors.push('email is required');
if (!data.email.includes('@'))  errors.push('email format invalid');
if (!data.gender)               errors.push('gender is required');
if (!data.date_of_birth)        errors.push('date_of_birth is required');
if (!data.location_city)        errors.push('location_city is required');
if (!data.location_country)     errors.push('location_country is required');
if (data.gdpr_consent !== true) errors.push('gdpr_consent must be true — hard stop');
if (data.ai_consent !== true)   errors.push('ai_consent must be true — hard stop');
if (!data._photos.headshot.length) errors.push('headshot photo is required');

if (errors.length > 0) {
  throw new Error('Validation failed: ' + errors.join(' | '));
}

return [{ json: data }];

const data = $('Code: Parse & Validate Form Data').first().json;

const batch_id = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
  var r = Math.random() * 16 | 0;
  var v = c === 'x' ? r : (r & 0x3 | 0x8);
  return v.toString(16);
});

const images_in_batch = 
  (data._photos.headshot.length > 0 ? 1 : 0) +
  (data._photos.full_body.length > 0 ? 1 : 0) +
  (data._photos.profile.length > 0 ? 1 : 0) +
  (data._photos.three_quarter.length > 0 ? 1 : 0) +
  (data._photos.polaroid.length > 0 ? 1 : 0);

const reapplication_eligible_date = new Date(
  Date.now() + 180 * 24 * 60 * 60 * 1000
).toISOString().split('T')[0];

return [{
  json: {
    ...data,
    batch_id: batch_id,
    images_in_batch: images_in_batch,
    reapplication_eligible_date: reapplication_eligible_date,
  }
}];

const data = $('Code: Parse & Validate Form Data').first().json;
const existing = $('Duplicate Application Check').first().json;

const previous_count = existing.reapplication_count || 0;

return [{
  json: {
    ...data,
    is_reapplication: true,
    reapplication_count: previous_count + 1,
  }
}];

const supabase_row = $input.first().json;
const form_data = $('Code: Generate Batch ID').first().json;

const intake_id = supabase_row.intake_id;
const batch_id = form_data.batch_id;
const agency_slug = form_data.agency_slug;

// Read thumbnail type from CLIENT CONFIG
const config = $('Read Agency Slug').first().json.fields;
const thumbnail_photo_type = (config['Thumbnail Photo Type'] || 'headshot').toLowerCase().replace(' ', '_');

// Build month prefix YYYY-MM
const now = new Date();
const month_prefix = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0');

const photos = [];
const photoTypes = ['headshot', 'full_body', 'profile', 'three_quarter', 'polaroid'];

photoTypes.forEach(type => {
  const photoArray = form_data._photos[type];
  if (photoArray && photoArray.length > 0) {
    photoArray.forEach(photo => {
      const ext = photo.mimeType === 'image/png' ? 'png'
                : photo.mimeType === 'image/jpeg' ? 'jpg'
                : photo.mimeType === 'image/webp' ? 'webp'
                : 'jpg';

      const r2_object_key = `${agency_slug}/intake/talent_prism/${month_prefix}/${intake_id}/${type}_${photo.id}.${ext}`;

      photos.push({
        intake_id:                intake_id,
        batch_id:                 batch_id,
        agency_slug:              agency_slug,
        photo_type:               type,
        tally_url:                photo.url,
        tally_id:                 photo.id,
        file_name:                photo.name,
        mime_type:                photo.mimeType,
        file_size_bytes:          photo.size,
        image_file_size_kb:       Math.round(photo.size / 1024),
        r2_object_key:            r2_object_key,
        is_thumbnail:             type === thumbnail_photo_type,
        processing_status:        'pending',
        photo_compliance_checked: false,
        tally_submission_time:    form_data.consent_date,
      });
    });
  }
});

return photos.map(p => ({ json: p }));

const data = $('Code: Generate Batch ID').first().json;
const config = $('Read Agency Slug').first().json.fields;
const gender = data.gender;

// ── READ THRESHOLDS FROM CONFIG ──────────────────────────────
const f = {
  min_height: parseFloat(config['(F) Min Height']) || null,
  max_height: parseFloat(config['(F) Max Height']) || null,
  min_bust:   parseFloat(config['(F) Min Bust'])   || null,
  max_bust:   parseFloat(config['(F) Max Bust'])   || null,
  min_waist:  parseFloat(config['(F) Min Waist'])  || null,
  max_waist:  parseFloat(config['(F) Max Waist'])  || null,
  min_hips:   parseFloat(config['(F) Min Hips'])   || null,
  max_hips:   parseFloat(config['(F) Max Hips'])   || null,
  min_shoe:   parseFloat(config['(F) Min Shoe'])   || null,
  max_shoe:   parseFloat(config['(F) Max Shoe'])   || null,
  min_age:    parseFloat(config['(F) Min Age'])    || null,
  max_age:    parseFloat(config['(F) Max Age'])    || null,
};

const m = {
  min_height: parseFloat(config['(M) Min Height']) || null,
  max_height: parseFloat(config['(M) Max Height']) || null,
  min_chest:  parseFloat(config['(M) Min Chest'])  || null,
  max_chest:  parseFloat(config['(M) Max Chest'])  || null,
  min_waist:  parseFloat(config['(M) Min Waist'])  || null,
  max_waist:  parseFloat(config['(M) Max Waist'])  || null,
  min_shoe:   parseFloat(config['(M) Min Shoe'])   || null,
  max_shoe:   parseFloat(config['(M) Max Shoe'])   || null,
  min_age:    parseFloat(config['(M) Min Age'])    || null,
  max_age:    parseFloat(config['(M) Max Age'])    || null,
};

const nb = {
  min_height: parseFloat(config['(NB) Min Height']) || null,
  max_height: parseFloat(config['(NB) Max Height']) || null,
  min_waist:  parseFloat(config['(NB) Min Waist'])  || null,
  max_waist:  parseFloat(config['(NB) Max Waist'])  || null,
  min_shoe:   parseFloat(config['(NB) Min Shoe'])   || null,
  max_shoe:   parseFloat(config['(NB) Max Shoe'])   || null,
  min_age:    parseFloat(config['(NB) Min Age'])    || null,
  max_age:    parseFloat(config['(NB) Max Age'])    || null,
};

// ── AGE CALCULATION ──────────────────────────────────────────
const dob = new Date(data.date_of_birth);
const today = new Date();
let age = today.getFullYear() - dob.getFullYear();
const mo = today.getMonth() - dob.getMonth();
if (mo < 0 || (mo === 0 && today.getDate() < dob.getDate())) age--;

// ── HELPER ───────────────────────────────────────────────────
const checkRange = (val, min, max, label) => {
  const errors = [];
  if (min !== null && val !== null && val < min)
    errors.push(`${label} ${val} below minimum ${min}`);
  if (max !== null && val !== null && val > max)
    errors.push(`${label} ${val} above maximum ${max}`);
  return errors;
};

const errors = [];

// ── FEMALE FILTERS ───────────────────────────────────────────
if (gender === 'Female') {
  errors.push(...checkRange(data.height_cm,    f.min_height, f.max_height, 'Height(cm)'));
  errors.push(...checkRange(data.bust_cm,      f.min_bust,   f.max_bust,   'Bust(cm)'));
  errors.push(...checkRange(data.waist_cm,     f.min_waist,  f.max_waist,  'Waist(cm)'));
  errors.push(...checkRange(data.hips_cm,      f.min_hips,   f.max_hips,   'Hips(cm)'));
  errors.push(...checkRange(data.shoe_size_eu, f.min_shoe,   f.max_shoe,   'Shoe(EU)'));
  errors.push(...checkRange(age,               f.min_age,    f.max_age,    'Age'));
}

// ── MALE FILTERS ─────────────────────────────────────────────
else if (gender === 'Male') {
  errors.push(...checkRange(data.height_cm,    m.min_height, m.max_height, 'Height(cm)'));
  errors.push(...checkRange(data.bust_cm,      m.min_chest,  m.max_chest,  'Chest(cm)'));
  errors.push(...checkRange(data.waist_cm,     m.min_waist,  m.max_waist,  'Waist(cm)'));
  errors.push(...checkRange(data.shoe_size_eu, m.min_shoe,   m.max_shoe,   'Shoe(EU)'));
  errors.push(...checkRange(age,               m.min_age,    m.max_age,    'Age'));
}

// ── NON-BINARY FILTERS ───────────────────────────────────────
else if (gender === 'Non Binary') {
  errors.push(...checkRange(data.height_cm,    nb.min_height, nb.max_height, 'Height(cm)'));
  errors.push(...checkRange(data.waist_cm,     nb.min_waist,  nb.max_waist,  'Waist(cm)'));
  errors.push(...checkRange(data.shoe_size_eu, nb.min_shoe,   nb.max_shoe,   'Shoe(EU)'));
  errors.push(...checkRange(age,               nb.min_age,    nb.max_age,    'Age'));
}

// ── TRANS → NON-BINARY PATH ──────────────────────────────────
else if (gender === 'Trans') {
  errors.push(...checkRange(data.height_cm,    nb.min_height, nb.max_height, 'Height(cm)'));
  errors.push(...checkRange(data.waist_cm,     nb.min_waist,  nb.max_waist,  'Waist(cm)'));
  errors.push(...checkRange(data.shoe_size_eu, nb.min_shoe,   nb.max_shoe,   'Shoe(EU)'));
  errors.push(...checkRange(age,               nb.min_age,    nb.max_age,    'Age'));
}

// ── PREFER NOT TO SAY → AGE CHECK ONLY ──────────────────────
else if (gender === 'Prefer Not to Say') {
  const min_age = Math.min(
    f.min_age || 99, m.min_age || 99, nb.min_age || 99
  );
  const max_age = Math.max(
    f.max_age || 0, m.max_age || 0, nb.max_age || 0
  );
  errors.push(...checkRange(age, min_age, max_age, 'Age'));
}

// ── RESULT ───────────────────────────────────────────────────
const gender_not_specified = gender === 'Prefer Not to Say';

if (errors.length > 0) {
  return [{
    json: {
      ...data,
      hard_filter_passed: false,
      hard_filter_fail_reason: errors.join(' | '),
      application_stage: 'hard_filter_fail',
    }
  }];
}

return [{
  json: {
    ...data,
    hard_filter_passed: true,
    hard_filter_fail_reason: gender_not_specified ? 'Gender Not Specified' : null,
    application_stage: 'screening',
  }
}];
